async function complete(role:string,value:unknown){const turn=lastTurn(role);if(role==='orchestrator'&&value&&typeof value==='object'&&'write_scope'in(value as object)){const task=modules.state.getState().tasks.find((row:any)=>row.orchestratorThreadId===turn.threadId);const selected=modules.state.getTask(task?.id)?.passes?.find((pass:any)=>pass.id===task?.currentPassId)?.selectedSkills||[];await recruit([{...workerPlan(),assignment:value as typeof assignment,skill_refs:selected.map((skill:any)=>skill.id)}]);return turn;}if(role==='worker'){fake.dshSessions.get(turn.threadId)?.complete(turn.turnId,value);return turn;}const owner=fake.threadOwners.get(turn.threadId)||fake.instance;owner.emit('notification','turn/completed',{threadId:turn.threadId,turn:{id:turn.turnId,status:'completed',items:[{type:'agentMessage',text:JSON.stringify(value)}]}});return turn;}
async function waitForRole(role:string){await waitFor(()=>fake.calls.some(row=>row.kind==='turn'&&row.role===role));const turn=lastTurn(role);await waitFor(()=>role==='worker'?isActiveWorkerTurn(turn.threadId):modules?.state.getState().tasks.some((task:any)=>task[`${role}ThreadId` as string]===turn.threadId&&task.activeTurnId===turn.turnId));return turn;}
function workerPlan(overrides:Partial<Assignment>={},effort:'max'='max',skill_refs:string[]=[]){return {name:'Implementation worker',step:'Implement the bounded requested change',depends_on:[],assignment:{...assignment,...overrides},effort,skill_refs};}
type WorkerPlan=ReturnType<typeof workerPlan>;
async function recruit(workers:WorkerPlan[]=[workerPlan({write_scope:[path.join(projectRoot,'src')]})]){const taskId=modules?.state.getState().activeTaskId;const beforePass=modules?.state.getTask(taskId)?.passes?.find((pass:any)=>pass.id===modules.state.getTask(taskId)?.currentPassId);const beforeTeamId=beforePass?.recruitmentTeam?.teamId;const workerTurnsBefore=turns('worker').length;const turn=lastTurn('orchestrator');const owner=fake.threadOwners.get(turn.threadId)||fake.agentInstance;const id=`recruit-${fake.turnCount}`;owner.emit('serverRequest',id,'item/tool/call',{threadId:turn.threadId,turnId:turn.turnId,namespace:'pseudoharness',tool:'recruit_workers',arguments:{workers}});await waitFor(()=>fake.calls.some(row=>row.kind==='server-response'&&row.id===id));const response=fake.calls.find(row=>row.kind==='server-response'&&row.id===id)?.result;if(response?.success!==true)throw new Error(`Recruitment fixture rejected: ${response?.contentItems?.[0]?.text||JSON.stringify(response)}`);owner.emit('notification','turn/completed',{threadId:turn.threadId,turn:{id:turn.turnId,status:'completed',items:[{type:'agentMessage',text:'The complete team is sealed; I will wait for the combined receipt.'}]}});await waitFor(()=>{const pass=modules?.state.getTask(taskId)?.passes?.find((row:any)=>row.id===beforePass?.id),team=pass?.recruitmentTeam;return !!team?.sealed&&team.teamId!==beforeTeamId&&team.workers.length===workers.length;});await waitFor(()=>turns('worker').length>workerTurnsBefore||modules?.state.getTask(taskId)?.passes?.some((pass:any)=>pass.recruitmentTeam?.workers.some((worker:any)=>['failed','blocked'].includes(worker.status))));const currentTeam=modules?.state.getTask(taskId)?.passes?.find((pass:any)=>pass.id===beforePass?.id)?.recruitmentTeam;const failed=currentTeam?.workers.find((worker:any)=>['failed','blocked'].includes(worker.status));if(failed)throw new Error(`Recruited worker did not start: ${failed.error||failed.status}`);return lastTurn('worker');}
async function runRecruitedTeamToReview(workerReceiptValue:unknown,integrationReceiptValue:unknown,qaEnabled=false){
  const {orchestrator,state}=await setup();const task=await orchestrator.submitTask('Add one bounded feature with a recruited worker and integration receipt.',undefined,[],[],undefined,undefined,qaEnabled);await complete('router',{route:'hard_task',rule_id:'hard_new_feature',justification:'This request introduces behavior.'});await waitForRole('orchestrator');await recruit([workerPlan({...assignment,write_scope:[path.join(projectRoot,'src')]})]);
  await waitFor(()=>turns('worker').length===1&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_plan',queries:['feature implementation constraints'],scope_summary:'Implement the bounded feature.'});await waitFor(()=>turns('worker').length===2&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_ready',summary:'No project context was needed for the fixture.'});await waitFor(()=>turns('worker').length===3&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:workerReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
  await waitFor(()=>state.getTask(task.id)?.passes?.[0]?.recruitmentTeam?.integration.status==='context_plan');await waitFor(()=>turns('worker').length===4&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_plan',queries:['integrate feature commit'],scope_summary:'Review the worker change.'});await waitFor(()=>turns('worker').length===5&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_ready',summary:'No additional integration context is required.'});await waitFor(()=>turns('worker').length===6&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:integrationReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});await waitFor(()=>turns('orchestrator').length===2&&state.getTask(task.id)?.phase==='reviewing');return {orchestrator,state,task};
}
async function completeCurrentSingleWorkerTeam(workerReceiptValue:unknown,integrationReceiptValue:unknown){
  const initial=turns('worker').length-1;
  await waitFor(()=>turns('worker').length>=initial+1&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_plan',queries:['correct current QA finding'],scope_summary:'Implement the evidence-backed correction.'});
  await waitFor(()=>turns('worker').length>=initial+2&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_ready',summary:'The correction scope is clear.'});
  await waitFor(()=>turns('worker').length>=initial+3&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:workerReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
  await waitFor(()=>turns('worker').length>=initial+4&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_plan',queries:['verify the corrected integration'],scope_summary:'Integrate and verify the correction.'});
  await waitFor(()=>turns('worker').length>=initial+5&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'context_ready',summary:'No additional integration context is required.'});
  await waitFor(()=>turns('worker').length>=initial+6&&isActiveWorkerTurn(lastTurn('worker').threadId));await complete('worker',{type:'receipt',receipt:integrationReceiptValue,decision_needed:null,evidence:[],options:[],recommendation:null,consequences:[]});
}
async function modelAgentMemCall(role:string,toolName:string,argumentsValue:Record<string,unknown>,result:unknown){const turn=lastTurn(role);if(turn.server==='deepseek'){const runtime=fake.dshSessions.get(turn.threadId);runtime.toolCall(`mcp__agentmem__${toolName}`,argumentsValue,result);await waitFor(()=>modules.state.getTask(taskIdForThread(turn.threadId))?.passes?.some((pass:any)=>pass.agentmemAudit?.calls?.some((call:any)=>call.threadId===turn.threadId&&call.method===toolName&&call.status==='completed')));return;}const owner=fake.threadOwners.get(turn.threadId)||fake.instance;const id=`${role}-${toolName}-${fake.calls.length}`;const item={id,type:'mcpToolCall',serverName:'agentmem',toolName,arguments:argumentsValue,status:'inProgress'};owner.emit('notification','item/started',{threadId:turn.threadId,turnId:turn.turnId,item});owner.emit('notification','item/completed',{threadId:turn.threadId,turnId:turn.turnId,item:{...item,status:'completed',result:{structuredContent:result}}});await waitFor(()=>modules?.state.getState().tasks.some((task:any)=>task.passes?.some((pass:any)=>pass.agentmemAudit?.calls?.some((call:any)=>call.id===`model:${turn.threadId}:${turn.turnId}:${id}`&&call.status==='completed'))));}
function taskIdForThread(threadId:string){return modules?.state.getState().tasks.find((task:any)=>task.passes?.some((pass:any)=>pass.recruitmentTeam?.workers.some((worker:any)=>worker.threadId===threadId)||pass.recruitmentTeam?.integration.threadId===threadId))?.id||'';}

afterEach(async()=>{await new Promise(resolve=>setImmediate(resolve));if(modules?.state)await modules.state.mutate(()=>{});if(modules?.orchestrator){await modules.orchestrator.shutdown();modules=null;}if(dataDirectory){const library=await import('../server/skill-library.js');library.closeSkillLibrary();}if(previousDataDirectory===undefined)delete process.env.PSEUDOHARNESS_DATA_DIR;else process.env.PSEUDOHARNESS_DATA_DIR=previousDataDirectory;if(originalCodexHome===undefined)delete process.env.CODEX_HOME;else process.env.CODEX_HOME=originalCodexHome;if(originalCodexProfile===undefined)delete process.env.CODEX_PROFILE;else process.env.CODEX_PROFILE=originalCodexProfile;if(dataDirectory)await rm(dataDirectory,{recursive:true,force:true,maxRetries:10,retryDelay:100});for(const home of testCodexHomes)await rm(home,{recursive:true,force:true,maxRetries:10,retryDelay:100});testCodexHomes=[];testCodexHome='';});
